function handleSort(columnKey) {
  setSortConfig(prevConfig => {
    if (prevConfig.key === columnKey && prevConfig.direction === 'asc') {
      return { key: columnKey, direction: 'desc' };
    }
    return { key: columnKey, direction: 'asc' };
  });
}

